using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class TestGroveAI {
 static EnemyController enemy;static EnemySpawner world;static AshenFrontierEncounterController[] controllers;static Transform player;static Rigidbody2D body;static int stage;static double began,nearAt;static List<string> results=new List<string>();
 static Vector2[] starts={new Vector2(-24.5f,16),new Vector2(-22,19.5f),new Vector2(-16,21)};
 static Vector2[] goals={new Vector2(-24.5f,11.5f),new Vector2(-22,16),new Vector2(-20.5f,21)};
 public static string Main(){world=UnityEngine.Object.FindAnyObjectByType<EnemySpawner>();controllers=UnityEngine.Object.FindObjectsByType<AshenFrontierEncounterController>(FindObjectsInactive.Exclude);foreach(var c in controllers)c.enabled=false;world.enabled=false;foreach(var e in EnemyController.ActiveControllers.ToArray())if(e)UnityEngine.Object.Destroy(e.gameObject);player=GameObject.Find("Player").transform;body=player.GetComponent<Rigidbody2D>();stage=0;Begin();EditorApplication.update+=Tick;return "Testing actual enemy pursuit across western bridge, cabin stairs and new northern bridge.";}
 static void Begin(){body.position=goals[stage];player.position=goals[stage];Physics2D.SyncTransforms();world.navigation.Invalidate();enemy=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DrownedGrove/Prefabs/bog_scout.prefab"),starts[stage],Quaternion.identity).GetComponent<EnemyController>();enemy.world=world;enemy.activeDuringDaytime=true;enemy.maxChaseDistanceFromOrigin=12;began=EditorApplication.timeSinceStartup;nearAt=0;}
 static void Tick(){if(!Application.isPlaying){Finish();return;}if(!enemy){results.Add("FAIL enemy missing");Finish();return;}float d=Vector2.Distance(enemy.transform.position,goals[stage]);if(d<1.35f&&nearAt==0)nearAt=EditorApplication.timeSinceStartup;
 if((nearAt>0&&EditorApplication.timeSinceStartup-nearAt>2)||EditorApplication.timeSinceStartup-began>18){results.Add((nearAt>0?"PASS":"FAIL")+" actual pursuit crossing "+stage+" start="+starts[stage]+" target="+goals[stage]+" end="+enemy.transform.position+" state="+enemy.State);UnityEngine.Object.Destroy(enemy.gameObject);stage++;if(stage==starts.Length){Finish();return;}Begin();}}
 static void Finish(){EditorApplication.update-=Tick;if(enemy && Application.isPlaying)UnityEngine.Object.Destroy(enemy.gameObject);foreach(var c in controllers)if(c)c.enabled=true;if(world)world.enabled=true;File.WriteAllLines("Design/DrownedGrove/EnemyCrossings.txt",results);}
}

